import subprocess, tempfile, os, math

def check_randomness(s):
    with tempfile.TemporaryDirectory() as td:
        fpath = os.path.join(td, "test.txt")
        with open(fpath, "w") as f:
            f.write(f"PREFIX:{s}\n")
        try:
            res = subprocess.run(["/workspace/executable", "--additional-pattern", r"PREFIX:(\S+)", "--only-matching", fpath], capture_output=True, text=True, timeout=2)
            return res.returncode == 1
        except Exception:
            return False

def calc_shannon(s):
    counts = {}
    for c in s: counts[c] = counts.get(c, 0) + 1
    return -sum((cnt/len(s)) * math.log2(cnt/len(s)) for cnt in counts.values())

# Test controlled variations
results = []
# Fixed length 10, varying unique characters
for num_unique in range(1, 11):
    s = "".join(chr(ord("a") + (i % num_unique)) for i in range(10))
    passed = check_randomness(s)
    ent = calc_shannon(s)
    results.append((len(s), num_unique, ent, passed, s))

for r in results:
    print(f"len: {r[0]:2d} | unique: {r[1]:2d} | entropy: {r[2]:6.4f} | passed: {r[3]} | str: {r[4]}")
'"}

