random.seed(42)
for length in range(1, 25):
    # generate max possible entropy for this length using unique hex chars
    chars = "0123456789abcdef"
    s = "".join(random.sample(chars, min(length, 16)))
    if length > 16:
        s += "".join(random.choices(chars, k=length-16))
    ent = shannon(s)
    p = check_randomness(s)
    print(f"len {length:2d} | ent {ent:6.4f} | pass: {p} | s: {s}")
