const DEFAULT_PATTERNS: &str = r#"[A-Za-z]+://\S{3,50}:(\S{8,50})@[\dA-Za-z#%&+./:=?_~-]+|\beyJ[\dA-Za-z=_-]+(?:\.[\dA-Za-z=_-]{3,}){1,4}|(?:gh[oprsu]|github_pat)_[\dA-Za-z_]{36}|glpat-[\dA-Za-z_=-]{20,22}|[rs]k_live_[\dA-Za-z]{24,247}|sq0i[a-z]{2}-[\dA-Za-z_-]{22,43}|sq0c[a-z]{2}-[\dA-Za-z_-]{40,50}|EAAA[\dA-Za-z+=-]{60}|AccountKey=[\d+/=A-Za-z]{88}|AIzaSy[\dA-Za-z_-]{33}|npm_[\dA-Za-z]{36}|//.+/:_authToken=[\dA-Za-z_-]+|xox[aboprs]-(?:\d+-)+[\da-z]+|<master>\{[\dA-Za-z]+\}</master>|https://hooks\.slack\.com/services/T[\dA-Za-z_]+/B[\dA-Za-z_]+/[\dA-Za-z_]+|SG\x2e[\dA-Za-z_-]{22}\.[\dA-Za-z_-]{43}|(?:AC|SK)[\da-z]{32}|[\da-f]{32}-us\d{1,2}|s-s4t2(?:af|ud)-[\da-f]{64}|PuTTY-User-Key-File-2|AGE-SECRET-KEY-1[\dA-Z]{58}|-{5}BEGIN DSA PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)|-{5}BEGIN EC PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)|-{5}BEGIN OPENSSH PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)|-{5}BEGIN PGP PRIVATE KEY BLOCK-{5}(?:$|[^-]{63,}-{5}END)|-{5}BEGIN PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)|-{5}BEGIN RSA PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)|-{5}BEGIN SSH2 ENCRYPTED PRIVATE KEY-{5}(?:$|[^-]{63,}-{5}END)|(?i:key|token|secret|password)\w*["']?]?\s*(?:[:=]|:=|=>|<-|>)\s*[\t "'`]?([\w+./=~\-\\`^]{15,90})(?:[\t\n "'`]|</|$)"#;

fn is_sequential(s: &str) -> bool {
    if s.len() < 3 {
        return false;
    }
    let chars: Vec<u8> = s.bytes().collect();
    if chars.iter().all(|&c| c == chars[0]) {
        return true;
    }
    let mut inc = true;
    for i in 1..chars.len() {
        if chars[i] as i16 - chars[i - 1] as i16 != 1 {
            inc = false;
            break;
        }
    }
    if inc {
        return true;
    }
    let mut dec = true;
    for i in 1..chars.len() {
        if chars[i - 1] as i16 - chars[i] as i16 != 1 {
            dec = false;
            break;
        }
    }
    if dec {
        return true;
    }
    false
}

fn calculate_entropy(s: &str) -> f64 {
    if s.is_empty() {
        return 0.0;
    }
    let mut counts = HashMap::new();
    for c in s.chars() {
        *counts.entry(c).or_insert(0) += 1;
    }
    let len = s.chars().count() as f64;
    let mut entropy = 0.0;
    for &count in counts.values() {
        let p = count as f64 / len;
        entropy -= p * p.log2();
    }
    entropy
}

fn is_hex(s: &str) -> bool {
    s.bytes().all(|b| b.is_ascii_hexdigit())
}

fn is_random(s: &str) -> bool {
    if s.len() <= 2 {
        return true;
    }
    if is_sequential(s) {
        return false;
    }
    let entropy = calculate_entropy(s);
    if is_hex(s) {
        entropy >= 3.0
    } else {
        entropy >= 4.5
    }
}

fn load_secrets_ignore() -> (HashSet<String>, Vec<String>) {
    let mut ignored_secrets = HashSet::new();
    let mut ignore_patterns = Vec::new();

    let candidates = vec![PathBuf::from(".secretsignore")];
    for p in candidates {
        if p.exists() {
            if let Ok(file) = File::open(p) {
                let reader = BufReader::new(file);
                let mut in_secrets = false;
                for line in reader.lines().flatten() {
                    let trimmed = line.trim();
                    if trimmed.is_empty() || trimmed.starts_with('#') {
                        continue;
                    }
                    if trimmed.eq_ignore_ascii_case("[secrets]") {
                        in_secrets = true;
                        continue;
                    }
                    if in_secrets {
                        ignored_secrets.insert(trimmed.to_string());
                    } else {
                        ignore_patterns.push(trimmed.to_string());
                    }
                }
            }
        }
    }
    (ignored_secrets, ignore_patterns)
}

fn install_pre_commit(target_dir: &str) -> i32 {
    let base = Path::new(target_dir);
    let git_dir = base.join(".git");
    if !git_dir.exists() || !git_dir.is_dir() {
        eprintln!("Error: .git directory not found");
        return 2;
    }
    let hooks_dir = git_dir.join("hooks");
    if let Err(e) = fs::create_dir_all(&hooks_dir) {
        eprintln!("Error creating hooks directory: {}", e);
        return 2;
    }
    let hook_file = hooks_dir.join("pre-commit");
    let cmd = "ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`\n";

    let mut content = String::new();
    if hook_file.exists() {
        if let Ok(existing) = fs::read_to_string(&hook_file) {
            content = existing;
        }
    }
    content.push_str(cmd);

    if let Err(e) = fs::write(&hook_file, content) {
        eprintln!("Error writing hook file: {}", e);
        return 2;
    }

    if let Ok(metadata) = fs::metadata(&hook_file) {
        let mut permissions = metadata.permissions();
        permissions.set_mode(0o744);
        let _ = fs::set_permissions(&hook_file, permissions);
    }

    0
}

fn main() {
    let matches = Command::new("ripsecrets")
        .version("0.1.11")
        .about("A command-line tool to prevent committing secret keys into your source code")
        .long_about("ripsecrets searches files and directories recursively for secret API keys.\nIt's primarily designed to be used as a pre-commit to prevent committing\nsecrets into version control.")
        .arg(
            Arg::new("install-pre-commit")
                .long("install-pre-commit")
                .action(ArgAction::SetTrue)
                .help("Install `ripsecrets` as a pre-commit hook automatically in git directory provided"),
        )
        .arg(
            Arg::new("strict-ignore")
                .long("strict-ignore")
                .action(ArgAction::SetTrue)
                .help("If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit"),
        )
        .arg(
            Arg::new("only-matching")
                .long("only-matching")
                .action(ArgAction::SetTrue)
                .help("Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line"),
        )
        .arg(
            Arg::new("additional-pattern")
                .long("additional-pattern")
                .value_name("ADDITIONAL_PATTERNS")
                .action(ArgAction::Append)
                .help("Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret"),
        )
        .arg(
            Arg::new("sources")
                .value_name("Source files")
                .action(ArgAction::Append)
                .help("Source files. Can be files or directories. Defaults to '.'"),
        )
        .get_matches();

    let sources: Vec<String> = matches
        .get_many::<String>("sources")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    if matches.get_flag("install-pre-commit") {
        let target = sources.first().map(|s| s.as_str()).unwrap_or(".");
        let exit_code = install_pre_commit(target);
        std::process::exit(exit_code);
    }

    let strict_ignore = matches.get_flag("strict-ignore");
    let only_matching = matches.get_flag("only-matching");
    let additional_patterns: Vec<String> = matches
        .get_many::<String>("additional-pattern")
        .map(|vals| vals.cloned().collect())
        .unwrap_or_default();

    let mut patterns = vec![DEFAULT_PATTERNS.to_string()];
    patterns.extend(additional_patterns);
    let combined_pattern = format!("(?:{})", patterns.join("|"));

    let re = match Regex::new(&combined_pattern) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(2);
        }
    };

    let (ignored_secrets, _ignore_patterns) = load_secrets_ignore();

    let paths_to_scan = if sources.is_empty() {
        vec![".".to_string()]
    } else {
        sources
    };

    let mut secrets_found = false;

    for source_path_str in paths_to_scan {
        let p = Path::new(&source_path_str);
        if p.is_dir() {
            let mut builder = WalkBuilder::new(p);
            builder.add_custom_ignore_filename(".secretsignore");
            let walker = builder.build();

            for entry in walker.flatten() {
                if entry.file_type().map_or(false, |ft| ft.is_file()) {
                    if scan_file(
                        entry.path(),
                        &re,
                        &ignored_secrets,
                        only_matching,
                        entry.path().display().to_string(),
                    ) {
                        secrets_found = true;
                    }
                }
            }
        } else {
            if strict_ignore && is_path_ignored(p) {
                continue;
            }
            if scan_file(p, &re, &ignored_secrets, only_matching, source_path_str.clone()) {
                secrets_found = true;
            }
        }
    }

    if secrets_found {
        std::process::exit(1);
    } else {
        std::process::exit(0);
    }
}

fn is_path_ignored(p: &Path) -> bool {
    if let Ok(file) = File::open(".secretsignore") {
        let reader = BufReader::new(file);
        for line in reader.lines().flatten() {
            let trimmed = line.trim();
            if trimmed.eq_ignore_ascii_case("[secrets]") {
                break;
            }
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            if let Ok(glob) = globset::Glob::new(trimmed) {
                let matcher = glob.compile_matcher();
                if matcher.is_match(p) {
                    return true;
                }
            }
        }
    }
    false
}

fn scan_file(
    path: &Path,
    re: &Regex,
    ignored_secrets: &HashSet<String>,
    only_matching: bool,
    display_path: String,
) -> bool {
    let file = match File::open(path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("{}: {}", display_path, e);
            return false;
        }
    };

    let reader = BufReader::new(file);
    let mut found = false;

    for (line_num_zero, line_res) in reader.split(b'\n').enumerate() {
        let line_bytes = match line_res {
            Ok(b) => b,
            Err(_) => continue,
        };
        let line_num = line_num_zero + 1;
        let line_str = String::from_utf8_lossy(&line_bytes);
        let trimmed_line = line_str.trim_end_matches('\r');

        let mut line_matched = false;

        for cap in re.captures_iter(trimmed_line) {
            let mut captured_val = None;
            for i in 1..cap.len() {
                if let Some(m) = cap.get(i) {
                    if !m.as_str().is_empty() {
                        captured_val = Some(m.as_str());
                        break;
                    }
                }
            }

            if let Some(val) = captured_val {
                if ignored_secrets.contains(val) {
                    continue;
                }
                if is_random(val) {
                    found = true;
                    line_matched = true;
                    if only_matching {
                        println!("{}:{}:{}", display_path, line_num, val);
                    }
                }
            } else if let Some(m0) = cap.get(0) {
                let val = m0.as_str();
                if ignored_secrets.contains(val) {
                    continue;
                }
                found = true;
                line_matched = true;
                if only_matching {
                    println!("{}:{}:{}", display_path, line_num, val);
                }
            }
        }

        if !only_matching && line_matched {
            println!("{}:{}:{}", display_path, line_num, trimmed_line);
        }
    }

    found
}
